import{c as e,Q as d,j as n,m as a}from"./chunks/framework.DOi4mjdC.js";const s="/assets/DataCopyGather.KRdH_YLs.png",r="/assets/gather.BdkjHW8Z.png",h=JSON.parse('{"title":"Gather","description":"","frontmatter":{},"headers":[{"level":1,"title":"Gather","slug":"gather"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"定义原型","slug":"定义原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/离散与聚合/Gather-50.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/离散与聚合/Gather-50.md"}'),i={name:"api/SIMD-API/基础API/Reg矢量计算/离散与聚合/Gather-50.md"};function l(p,t,g,o,u,_){return d(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="gather" tabindex="-1">Gather <a class="header-anchor" href="#gather" aria-label="Permalink to &quot;Gather&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><ul><li><p>收集UB中的元素</p><p>给定源操作数在UB中的基地址和索引，Gather指令根据索引位置将源操作数按元素收集到结果寄存器张量中。收集过程如下图所示：</p><p><img src="'+s+'" alt=""></p></li><li><p>收集RegTensor中的元素</p><p>根据索引位置indexReg将源操作数srcReg按元素收集到结果dstReg中。收集过程如下图所示：</p><p><img src="'+r+`" alt=""></p></li></ul><h2 id="定义原型" tabindex="-1">定义原型 <a class="header-anchor" href="#定义原型" aria-label="Permalink to &quot;定义原型&quot;">​</a></h2><ul><li><p>收集UB中的元素</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T0 = DefaultType, typename T1, typename T2 = DefaultType, typename T3, typename T4&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void Gather(T3&amp; dstReg, __ubuf__ T1* baseAddr, T4&amp; index, MaskReg&amp; mask)</span></span></code></pre></div></li><li><p>收集RegTensor中的元素</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, typename U = DefaultType, typename S, typename V&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void Gather(S&amp; dstReg, S&amp; srcReg, V&amp; indexReg)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><ul><li><p>收集UB中的元素</p><p><strong>表 1</strong> 模板参数说明</p></li></ul><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T0</td><td>目的操作数的数据类型。</td></tr><tr><td>T1</td><td>源操作数的数据类型。</td></tr><tr><td>T2</td><td>索引值的数据类型。</td></tr><tr><td>T3</td><td>目的操作数的RegTensor类型， 例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr><tr><td>T4</td><td>索引值的RegTensor类型，例如RegTensor&lt;uint16_t&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><pre><code>**表 2**  函数参数说明
</code></pre><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。 T0数据类型需要与T1和T2数据类型配套使用。类型配套对应表详见约束说明。 支持的数据类型详见表5。</td></tr><tr><td>baseAddr</td><td>输入</td><td>源操作数在UB中的基地址。 类型为UB指针。 T1数据类型需要与T0和T2数据类型配套使用。类型配套对应表详见约束说明。 支持的数据类型详见表5。</td></tr><tr><td>index</td><td>输入</td><td>dstReg中的每个元素在UB中相对于baseAddr的索引位置。地址偏移量要大于等于0。 类型为RegTensor。 T2数据类型需要与T0和T1数据类型配套使用。类型配套对应表详见约束说明。 支持的数据类型详见表5。</td></tr><tr><td>mask</td><td>输入</td><td>src element操作有效指示，详细说明请参考MaskReg。</td></tr></tbody></table><ul><li><p>收集RegTensor中的元素</p><p><strong>表 3</strong> 模板参数说明</p></li></ul><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数和源操作数的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：b8/b16/b32</td></tr><tr><td>U</td><td>索引值的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t/uint16_t/uint32_t</td></tr><tr><td>S</td><td>目的操作数的RegTensor类型，例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr><tr><td>V</td><td>索引值的RegTensor类型，例如RegTensor&lt;uint16_t&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><pre><code>**表 4**  函数参数说明
</code></pre><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg</td><td>输入</td><td>源操作数。 类型为RegTensor。 数据类型需要与目的操作数保持一致。</td></tr><tr><td>indexReg</td><td>输入</td><td>数据索引。 类型为RegTensor。 数据类型的位宽需要与目的操作数的位宽保持一致。 srcReg为RegTensor类型，位宽是固定的VL，存储的元素个数固定。如果indexReg中索引值超出当前RegTensor中能存储的最大数据元素个数时，按照如下方式处理：设定当前RegTensor所能存储的最大数据元素个数为vlLength，indexReg中索引值为i，索引值更新为i % vlLength。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>收集UB中的元素 <ul><li><p>T0，T1和T2数据类型需要配套使用。配套关系如下表：</p><p><strong>表 5</strong> Gather操作数数据类型对应表</p></li></ul></li></ul><table tabindex="0"><thead><tr><th>T0数据类型</th><th>T1数据类型</th><th>T2数据类型</th></tr></thead><tbody><tr><td>int16_t</td><td>int8_t</td><td>uint16_t</td></tr><tr><td>uint16_t</td><td>uint8_t</td><td>uint16_t</td></tr><tr><td>int16_t</td><td>int16_t</td><td>uint16_t</td></tr><tr><td>uint16_t</td><td>uint16_t</td><td>uint16_t</td></tr><tr><td>half</td><td>half</td><td>uint16_t</td></tr><tr><td>bfloat16_t</td><td>bfloat16_t</td><td>uint16_t</td></tr><tr><td>int32_t</td><td>int32_t</td><td>uint32_t</td></tr><tr><td>uint32_t</td><td>uint32_t</td><td>uint32_t</td></tr><tr><td>float</td><td>float</td><td>uint32_t</td></tr><tr><td>uint64_t</td><td>uint64_t</td><td>uint32_t</td></tr><tr><td>int64_t</td><td>int64_t</td><td>uint32_t</td></tr><tr><td>uint64_t</td><td>uint64_t</td><td>uint64_t</td></tr><tr><td>int64_t</td><td>int64_t</td><td>uint64_t</td></tr></tbody></table><pre><code>-   当T1为B8数据类型时，T0为B16类型，这种情况下目的操作数的低8位与源操作数相同，高8位自动补0。例如T1为int8数据类型：

    40=0b00101000 -\\&gt; 0b0000000000101000，扩充至16位后等于40；

    -40=0b11011000 -\\&gt; 0b0000000011011000，扩充至16位后等于216。

-   当T1为B64数据类型时，T0，T1，T2，T4, T3数据类型只支持以下组合:
</code></pre><table tabindex="0"><thead><tr><th>T0数据类型</th><th>T1数据类型</th><th>T2数据类型</th><th>T4数据类型</th><th>T3数据类型</th><th>备注</th></tr></thead><tbody><tr><td>B64</td><td>B64</td><td>uint32_t</td><td>RegTensor&lt;uint32_t&gt;</td><td>RegTensor&lt;uint64_t, RegTraitNumOne&gt;</td><td>index的前32个数有效</td></tr><tr><td>B64</td><td>B64</td><td>uint32_t</td><td>RegTensor&lt;uint32_t&gt;</td><td>RegTensor&lt;int64_t, RegTraitNumOne&gt;</td><td>index的前32个数有效</td></tr><tr><td>B64</td><td>B64</td><td>uint32_t</td><td>RegTensor&lt;uint32_t&gt;</td><td>RegTensor&lt;uint64_t, RegTraitNumTwo&gt;</td><td>-</td></tr><tr><td>B64</td><td>B64</td><td>uint32_t</td><td>RegTensor&lt;uint32_t&gt;</td><td>RegTensor&lt;int64_t, RegTraitNumTwo&gt;</td><td>-</td></tr><tr><td>B64</td><td>B64</td><td>uint64_t</td><td>RegTensor&lt;uint64_t, RegTraitNumOne&gt;</td><td>RegTensor&lt;uint64_t, RegTraitNumOne&gt;</td><td>-</td></tr><tr><td>B64</td><td>B64</td><td>uint64_t</td><td>RegTensor&lt;uint64_t, RegTraitNumOne&gt;</td><td>RegTensor&lt;int64_t, RegTraitNumOne&gt;</td><td>-</td></tr><tr><td>B64</td><td>B64</td><td>uint64_t</td><td>RegTensor&lt;uint64_t, RegTraitNumTwo&gt;</td><td>RegTensor&lt;uint64_t, RegTraitNumOne&gt;</td><td>index的前32个数有效</td></tr><tr><td>B64</td><td>B64</td><td>uint64_t</td><td>RegTensor&lt;uint64_t, RegTraitNumTwo&gt;</td><td>RegTensor&lt;int64_t, RegTraitNumOne&gt;</td><td>index的前32个数有效</td></tr><tr><td>B64</td><td>B64</td><td>uint64_t</td><td>RegTensor&lt;uint64_t, RegTraitNumTwo&gt;</td><td>RegTensor&lt;uint64_t, RegTraitNumTwo&gt;</td><td>-</td></tr><tr><td>B64</td><td>B64</td><td>uint64_t</td><td>RegTensor&lt;uint64_t, RegTraitNumTwo&gt;</td><td>RegTensor&lt;int64_t, RegTraitNumTwo&gt;</td><td>-</td></tr></tbody></table><ul><li><p>收集RegTensor中的元素</p><p>无约束</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>收集UB中的元素</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void GatherVF(__ubuf__ T* dstAddr, __ubuf__ T* src0Addr, __ubuf__ U* src1Addr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;U&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;    </span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg, src1Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::Gather(dstReg, src0Addr, srcReg, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>收集RegTensor中的元素</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void GatherVF(__ubuf__ T* dstAddr, __ubuf__ T* src0Addr, __ubuf__ U* src1Addr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg0, dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;U&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;</span></span>
<span class="line"><span>    AscendC::Reg::LoadAlign(srcReg1, src1Addr);</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, src0Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::Gather(dstReg, srcReg0, srcReg1);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,24)])])}const T=e(i,[["render",l]]);export{h as __pageData,T as default};
